package com.example.shop;

import static java.util.Objects.requireNonNull;

import java.util.ArrayList;
import java.util.List;

import org.example.money.Price;

public class Basket implements Iterable<Item>, AutoCloseable {
    private static final int LIMIT = 10;
    private final List<Item> items = new ArrayList<>();

    public Basket(Item first) {
        add(requireNonNull(first));
    }

    public void add(Item item) {
        if (items.size() >= LIMIT && !item.isFree()) {
            throw new IllegalStateException("The basket is full: " + items.size() + " items");
        } else {
            items.add(item);
        }
    }

    public Price total(int discountPercent, boolean roundToWholeUnits) throws InvalidPriceException {
        int sum = 0;
        for (Item item : items) {
            sum += item.price() * (100 - discountPercent) / 100;
        }
        try {
            return Price.of(sum).rounded(roundToWholeUnits).withCurrency("EUR")
                    .withNote("The total after the discount of " + discountPercent + "%").checked();
        } catch (IllegalArgumentException e) {
            throw new InvalidPriceException(e);
        } finally {
            switch (items.size()) {
                case 0:
                    break;
                default:
                    synchronized (this) {
                        items.trimToSize();
                    }
            }
        }
    }

    @Override
    public void close() {
        items.clear();
    }
}
